diff --git a/internal/serviceclient/user_service/client.go b/internal/serviceclient/user_service/client.go
new file mode 100644
index 0000000..95bff45
--- /dev/null
+++ b/internal/serviceclient/user_service/client.go
@@ -0,0 +1,218 @@
+// Package user_service provides a typed HTTP client for the user-service internal API.
+// It caches validated sessions in an in-process LRU cache with a configurable TTL
+// to avoid round-tripping on every request.
+package user_service
+
+import (
+	"bytes"
+	"container/list"
+	"context"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"io"
+	"net/http"
+	"sync"
+	"time"
+)
+
+// ErrUnauthenticated is returned when the session is missing, expired, or invalid.
+var ErrUnauthenticated = errors.New("unauthenticated")
+
+// ErrServiceUnavailable is returned when the user-service cannot be reached or returns 5xx.
+var ErrServiceUnavailable = errors.New("user-service unavailable")
+
+// SessionInfo holds the result of a successful session validation.
+type SessionInfo struct {
+	UserID                 string   `json:"user_id"`
+	OrganizationID         string   `json:"organization_id"`
+	AccessibleWorkspaceIDs []string `json:"accessible_workspace_ids"`
+}
+
+// validateResponse is the wire shape of POST /internal/sessions/validate.
+type validateResponse struct {
+	UserID                 string   `json:"user_id"`
+	OrganizationID         string   `json:"organization_id"`
+	AccessibleWorkspaceIDs []string `json:"accessible_workspace_ids"`
+}
+
+type cacheEntry struct {
+	info    *SessionInfo
+	expires time.Time
+	elem    *list.Element
+}
+
+// Client calls POST /internal/sessions/validate on user-service and caches results.
+type Client struct {
+	baseURL    string
+	token      string
+	httpClient *http.Client
+
+	mu      sync.Mutex
+	cache   map[string]*cacheEntry
+	lru     *list.List // front = most recently used
+	maxSize int
+	ttl     time.Duration
+}
+
+// Config holds the options for constructing a Client.
+type Config struct {
+	InternalURL string
+	Token       string
+	// CacheSize is the maximum number of sessions to cache. Default 1024.
+	CacheSize int
+	// CacheTTL is how long a validated session is cached. Default 30s.
+	CacheTTL time.Duration
+}
+
+// New creates a Client. It panics if InternalURL or Token is empty.
+func New(cfg Config) *Client {
+	if cfg.InternalURL == "" {
+		panic("user_service.Client: InternalURL must not be empty")
+	}
+	if cfg.Token == "" {
+		panic("user_service.Client: Token must not be empty")
+	}
+	if cfg.CacheSize <= 0 {
+		cfg.CacheSize = 1024
+	}
+	if cfg.CacheTTL <= 0 {
+		cfg.CacheTTL = 30 * time.Second
+	}
+	return &Client{
+		baseURL: cfg.InternalURL,
+		token:   cfg.Token,
+		httpClient: &http.Client{
+			Timeout: 5 * time.Second,
+		},
+		cache:   make(map[string]*cacheEntry, cfg.CacheSize),
+		lru:     list.New(),
+		maxSize: cfg.CacheSize,
+		ttl:     cfg.CacheTTL,
+	}
+}
+
+// ValidateSession validates a session cookie value against user-service.
+// Returns ErrUnauthenticated on 401/403, ErrServiceUnavailable on transport/5xx errors.
+// Results are cached with the configured TTL.
+func (c *Client) ValidateSession(ctx context.Context, cookieValue string) (*SessionInfo, error) {
+	if info, ok := c.getFromCache(cookieValue); ok {
+		return info, nil
+	}
+
+	info, err := c.callValidate(ctx, cookieValue)
+	if err != nil {
+		return nil, err
+	}
+
+	c.putInCache(cookieValue, info)
+	return info, nil
+}
+
+// Invalidate removes a session from the cache (for explicit logout hooks).
+func (c *Client) Invalidate(cookieValue string) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	if entry, ok := c.cache[cookieValue]; ok {
+		c.lru.Remove(entry.elem)
+		delete(c.cache, cookieValue)
+	}
+}
+
+func (c *Client) getFromCache(key string) (*SessionInfo, bool) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	entry, ok := c.cache[key]
+	if !ok {
+		return nil, false
+	}
+	if time.Now().After(entry.expires) {
+		c.lru.Remove(entry.elem)
+		delete(c.cache, key)
+		return nil, false
+	}
+	c.lru.MoveToFront(entry.elem)
+	return entry.info, true
+}
+
+func (c *Client) putInCache(key string, info *SessionInfo) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+
+	if entry, ok := c.cache[key]; ok {
+		entry.info = info
+		entry.expires = time.Now().Add(c.ttl)
+		c.lru.MoveToFront(entry.elem)
+		return
+	}
+
+	for c.lru.Len() >= c.maxSize {
+		oldest := c.lru.Back()
+		if oldest == nil {
+			break
+		}
+		oldKey, _ := oldest.Value.(string)
+		c.lru.Remove(oldest)
+		delete(c.cache, oldKey)
+	}
+
+	elem := c.lru.PushFront(key)
+	c.cache[key] = &cacheEntry{
+		info:    info,
+		expires: time.Now().Add(c.ttl),
+		elem:    elem,
+	}
+}
+
+func (c *Client) callValidate(ctx context.Context, cookieValue string) (*SessionInfo, error) {
+	body, err := json.Marshal(map[string]string{"session_cookie": cookieValue})
+	if err != nil {
+		return nil, fmt.Errorf("marshal request: %w", err)
+	}
+
+	req, err := http.NewRequestWithContext(ctx, http.MethodPost,
+		c.baseURL+"/internal/sessions/validate", bytes.NewReader(body))
+	if err != nil {
+		return nil, fmt.Errorf("build request: %w", err)
+	}
+	req.Header.Set("Content-Type", "application/json")
+	req.Header.Set("Authorization", "Bearer "+c.token)
+
+	resp, err := c.httpClient.Do(req)
+	if err != nil {
+		return nil, fmt.Errorf("%w: %w", ErrServiceUnavailable, err)
+	}
+	defer func() { _ = resp.Body.Close() }()
+
+	switch {
+	case resp.StatusCode == http.StatusUnauthorized || resp.StatusCode == http.StatusForbidden:
+		return nil, ErrUnauthenticated
+	case resp.StatusCode >= 500:
+		return nil, fmt.Errorf("%w: status %d", ErrServiceUnavailable, resp.StatusCode)
+	case resp.StatusCode != http.StatusOK:
+		return nil, fmt.Errorf("%w: unexpected status %d", ErrServiceUnavailable, resp.StatusCode)
+	}
+
+	raw, err := io.ReadAll(resp.Body)
+	if err != nil {
+		return nil, fmt.Errorf("%w: read body: %w", ErrServiceUnavailable, err)
+	}
+
+	var vr validateResponse
+	if err := json.Unmarshal(raw, &vr); err != nil {
+		return nil, fmt.Errorf("%w: decode response: %w", ErrServiceUnavailable, err)
+	}
+
+	if vr.UserID == "" {
+		return nil, ErrUnauthenticated
+	}
+	if vr.AccessibleWorkspaceIDs == nil {
+		vr.AccessibleWorkspaceIDs = []string{}
+	}
+
+	return &SessionInfo{
+		UserID:                 vr.UserID,
+		OrganizationID:         vr.OrganizationID,
+		AccessibleWorkspaceIDs: vr.AccessibleWorkspaceIDs,
+	}, nil
+}
