+		t.Errorf("encode response: %v", err)
+	}
+}
+
+func TestValidateSession_Success(t *testing.T) {
+	srv := makeServer(t, func(w http.ResponseWriter, r *http.Request) {
+		if r.Method != http.MethodPost || r.URL.Path != "/internal/sessions/validate" {
+			t.Errorf("unexpected request: %s %s", r.Method, r.URL.Path)
+		}
+		if r.Header.Get("Authorization") != "Bearer test-token" {
+			t.Errorf("missing or wrong Authorization header: %q", r.Header.Get("Authorization"))
+		}
+		w.Header().Set("Content-Type", "application/json")
+		encodeJSON(t, w, map[string]interface{}{
+			"user_id":                  "user-123",
+			"organization_id":          "org-456",
+			"accessible_workspace_ids": []string{"ws-aaa", "ws-bbb"},
+		})
+	})
+
+	client := newClient(t, srv.URL)
+	info, err := client.ValidateSession(context.Background(), "my-session-cookie")
+	if err != nil {
+		t.Fatalf("unexpected error: %v", err)
+	}
+	if info.UserID != "user-123" {
+		t.Errorf("expected user_id=user-123, got %q", info.UserID)
+	}
+	if info.OrganizationID != "org-456" {
+		t.Errorf("expected organization_id=org-456, got %q", info.OrganizationID)
+	}
+	if len(info.AccessibleWorkspaceIDs) != 2 {
+		t.Errorf("expected 2 accessible workspaces, got %d", len(info.AccessibleWorkspaceIDs))
+	}
