func TestErrorResponseShape(t *testing.T) {
	db := &fakeDB{}
	r := newTestRouter(db, &fakeAdapter{})

	w := httptest.NewRecorder()
	req, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, "/api/workspaces/"+handlerTestWSID, nil)
	r.ServeHTTP(w, req)

	apiErr := decodeAPIError(t, w.Body.Bytes())
	if apiErr.Code == "" {
		t.Error("expected non-empty error code")
	}
	if apiErr.Message == "" {
		t.Error("expected non-empty error message")
	}
	if apiErr.Source != string(domain.ErrorSourceDatabase) {
		t.Errorf("expected error source %q, got %q", domain.ErrorSourceDatabase, apiErr.Source)
	}
}
